"""Behavioral prompts. Scoring is rubric-based (app/engine/behavioral.py), so components here are
light: they encode what the question specifically demands, and followups encode the pressure a
banker applies. `behavioral_category` keys into the candidate's story bank categories."""
from app.knowledge.bank import Q, C, M, F

T = "behavioral"


def B(id, skill, cat, text, demands, followups, notes, difficulty=2, tags=None):
    comps = [C(d[0], d[1], d[2], required=d[3] if len(d) > 3 else False) for d in demands]
    return Q(id, T, cat, skill, difficulty, text, comps, [], followups, notes, kind="behavioral",
             answer_type="story", behavioral_category=cat, tags=tags or [])


